add_action( 'woocommerce_single_product_summary', 'perfectpixel_links_to_product_tabs', 21 );

function perfectpixel_links_to_product_tabs() {
	$tabs = apply_filters( 'woocommerce_product_tabs', array() );
	if ( ! $tabs ) {
		return;
	}
	$links = array();
	foreach ( $tabs as $key => $tab ) {
		$title   = wp_strip_all_tags( apply_filters( 'woocommerce_product_' . $key . '_tab_title', $tab['title'], $key ) );
		$links[] = '<a href="#tab-' . esc_attr( $key ) . '" data-perfectpixel-tab="' . esc_attr( $key ) . '">' . esc_html( $title ) . '</a>';
	}
	echo '<p class="perfectpixel-tab-links">' . esc_html( '{{tab_links_label}}' ) . ' ' . implode( ' &middot; ', $links ) . '</p>';
	?>
	<script>
	document.addEventListener( 'click', function ( e ) {
		var link = e.target.closest( '[data-perfectpixel-tab]' );
		if ( ! link ) {
			return;
		}
		var key    = link.getAttribute( 'data-perfectpixel-tab' );
		var opener = document.querySelector( '.wc-tabs a[href="#tab-' + key + '"]' );
		var target = document.getElementById( 'tab-' + key );
		if ( ! target ) {
			return;
		}
		e.preventDefault();
		if ( opener ) {
			opener.click();
		}
		( opener ? opener.closest( '.woocommerce-tabs' ) : target ).scrollIntoView( { behavior: 'smooth', block: 'start' } );
	} );
	</script>
	<?php
}
